import assert from "node:assert/strict";
import fs from "node:fs/promises";
import path from "node:path";
import { createHash } from "node:crypto";
import { execFileSync, spawnSync } from "node:child_process";
import { _electron, expect } from "@playwright/test";
import ffprobe from "ffprobe-static";
import ffmpeg from "ffmpeg-static";
import { fileURLToPath } from "node:url";
// Explicit, isolated packaged UI test. The supplied fixture must be generated by
// smoke-offline-speech.mjs; never use a customer's recording or existing profile.
const args = process.argv.slice(2);
if (!args.includes("--run") || args.includes("--help")) {
	console.log(
		"Usage: node scripts/smoke-offline-tools.mjs --run --fixture <synthetic fixture.json from smoke-offline-speech.mjs> [--executable <Recordly.exe>]\nTests real scene/Sherpa/RNNoise IPC, A-B UI, save/Undo/reopen and H264/AAC export using an isolated profile. No recording, model download, paid API or upload.",
	);
	process.exit(0);
}
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
let executable = path.join(root, "release/offline-tools-test/win-unpacked/Recordly.exe"),
	fixturePath;
for (let i = 0; i < args.length; i++) {
	if (args[i] === "--run") continue;
	if (
		(args[i] === "--fixture" || args[i] === "--executable") &&
		args[i + 1] &&
		!args[i + 1].startsWith("--")
	) {
		const key = args[i],
			value = path.resolve(args[++i]);
		if (key === "--fixture") fixturePath = value;
		else executable = value;
	} else throw Error("Invalid smoke-test arguments");
}
assert(fixturePath, "Pass an explicitly generated synthetic fixture.json");
fixturePath = await fs.realpath(fixturePath);
const fixtureDir = path.dirname(fixturePath),
	parent = await fs.realpath(path.join(root, ".tmp/offline-speech-smoke"));
assert(
	fixtureDir.startsWith(parent + path.sep),
	"Fixture must remain inside the isolated speech-test directory",
);
const fixture = JSON.parse(await fs.readFile(fixturePath, "utf8"));
assert(fixture.syntheticOnly);
const input = fixture.media;
assert(path.dirname(input) === fixtureDir);
const work = await fs.mkdtemp(path.join(root, ".tmp/tools-package-smoke-")),
	profile = path.join(work, "profile"),
	output = path.join(work, "export.mp4");
await fs.mkdir(profile);
await fs.writeFile(
	path.join(profile, "app-settings.json"),
	JSON.stringify({ "recordly.onboarding.v1.seen": true }),
);
const env = { ...process.env };
for (const key of Object.keys(env))
	if (
		key.startsWith("RECORDLY_") ||
		key === "ELECTRON_RUN_AS_NODE" ||
		key === "VITE_DEV_SERVER_URL"
	)
		delete env[key];
Object.assign(env, {
	RECORDLY_DIAGNOSTICS_USER_DATA: profile,
	RECORDLY_DEV_OPEN_RECORDING_INPUT: input,
	RECORDLY_DISABLE_AUTO_UPDATES: "1",
});
const hash = async (file) =>
	createHash("sha256")
		.update(await fs.readFile(file))
		.digest("hex");
const originalHash = await hash(input),
	report = { success: false, work, checks: [] };
let app;
try {
	app = await _electron.launch({ executablePath: executable, env, timeout: 120000 });
	await app.evaluate(({ session, dialog }, output) => {
		session.defaultSession.webRequest.onBeforeRequest(
			{ urls: ["http://*/*", "https://*/*"] },
			(details, done) =>
				done({ cancel: !/^https?:\/\/(127\.0\.0\.1|localhost)(:|\/)/.test(details.url) }),
		);
		dialog.showSaveDialog = async () => ({ canceled: false, filePath: output });
	}, output);
	const page = await app.firstWindow();
	page.setDefaultTimeout(60000);
	await expect(page.locator('[data-variant="clip"]')).toHaveCount(1, { timeout: 90000 });
	const status = await page.evaluate(() => window.electronAPI.getOfflineToolsStatus());
	assert(Object.values(status).every((x) => x.available));
	report.checks.push("all bundled tools available");
	await page.getByRole("button", { name: "Auto edit plan", exact: true }).click();
	const panel = page.locator("[data-auto-edit-panel]"),
		tools = panel.locator("[data-offline-tools]");
	await tools.locator("summary").click();
	await tools.getByRole("button", { name: "Detect scenes", exact: true }).click();
	await expect(tools.getByText(/scenes, sampled frame timing/)).toBeVisible({ timeout: 120000 });
	report.checks.push("packaged scene IPC and isolated Python returned actual scene boundaries");
	await tools
		.getByRole("button", { name: "Generate comparison transcript", exact: true })
		.click();
	await expect(tools.getByText(/Click the blue save button/i)).toBeVisible({ timeout: 180000 });
	report.checks.push("packaged Sherpa IPC recognized actual synthetic speech");
	await tools.getByLabel("Denoise track").selectOption("mixed");
	await tools.getByRole("button", { name: "Prepare voice comparison", exact: true }).click();
	await expect(tools.locator("audio")).toHaveCount(2, { timeout: 120000 });
	await expect(tools.getByRole("alert")).toHaveCount(0);
	await tools.getByRole("button", { name: "Apply reviewed result", exact: true }).click();
	await expect(
		tools.getByText("Edits changed. Generate a fresh result before applying.", { exact: true }),
	).toBeVisible();
	await panel.screenshot({ path: path.join(work, "voice-comparison.png") });
	await panel.getByRole("button", { name: "Close", exact: true }).click();
	await app.evaluate(({ BrowserWindow }) =>
		BrowserWindow.getAllWindows()
			.find((w) => w.webContents.getURL().includes("windowType=editor"))
			?.webContents.send("menu-save-project"),
	);
	const directory = await page.evaluate(() => window.electronAPI.getProjectsDirectory());
	assert(directory.success && directory.path.startsWith(profile + path.sep));
	let saved;
	await expect
		.poll(
			async () => {
				for (const name of await fs.readdir(directory.path)) {
					if (!name.endsWith(".recordly")) continue;
					try {
						const file = path.join(directory.path, name),
							project = JSON.parse(await fs.readFile(file, "utf8"));
						const groups = Object.values(
							project.editor.sourceAudioTrackSettingsByClip ?? {},
						);
						if (groups.some((g) => g.mixed?.voiceEnhancement?.enabled)) {
							saved = { file, project };
							return true;
						}
					} catch {
						/* The project save may still be completing. */
					}
				}
				return false;
			},
			{ timeout: 60000 },
		)
		.toBe(true);
	const asset = Object.values(saved.project.editor.sourceAudioTrackSettingsByClip).find(
		(g) => g.mixed?.voiceEnhancement?.enabled,
	).mixed.voiceEnhancement;
	assert(asset.originalPath === input && asset.audioPath !== input && asset.samples > 0);
	assert(asset.audioPath.startsWith(profile + path.sep));
	const copy = path.join(work, "voice-enhanced.recordly");
	await fs.copyFile(saved.file, copy);
	report.asset = asset;
	report.checks.push("RNNoise applied as separate persisted track setting");
	await page.getByRole("button", { name: "Undo", exact: true }).click();
	await app.evaluate(({ BrowserWindow }) =>
		BrowserWindow.getAllWindows()
			.find((w) => w.webContents.getURL().includes("windowType=editor"))
			?.webContents.send("menu-save-project"),
	);
	await expect
		.poll(
			async () => {
				try {
					const project = JSON.parse(await fs.readFile(saved.file, "utf8"));
					return Object.values(project.editor.sourceAudioTrackSettingsByClip ?? {}).every(
						(g) => !g.mixed?.voiceEnhancement?.enabled,
					);
				} catch {
					return false;
				}
			},
			{ timeout: 60000 },
		)
		.toBe(true);
	report.checks.push("one Undo restores original audio settings");
	await app.evaluate(({ dialog }, file) => {
		dialog.showOpenDialog = async () => ({ canceled: false, filePaths: [file] });
	}, copy);
	await page.getByRole("button", { name: "Home", exact: true }).click();
	const home = page.getByRole("dialog", { name: "Projects dashboard", exact: true });
	await home
		.getByRole("complementary", { name: "Library navigation" })
		.getByRole("button", { name: "Import video", exact: true })
		.click();
	await expect(home).not.toBeVisible();
	const approval = await page.evaluate(
		(file) => window.electronAPI.getLocalMediaUrl(file),
		asset.audioPath,
	);
	assert(approval.success);
	report.checks.push("saved project reopens with approved derived audio reference");
	await page.getByRole("button", { name: "Export", exact: true }).click();
	await page.getByRole("row", { name: "Local", exact: true }).click();
	await page.getByRole("button", { name: "Export Video", exact: true }).click();
	let probe;
	await expect
		.poll(
			async () => {
				try {
					probe = JSON.parse(
						execFileSync(
							ffprobe.path,
							["-v", "error", "-show_streams", "-show_format", "-of", "json", output],
							{ encoding: "utf8", windowsHide: true, timeout: 10000 },
						),
					);
					return probe.streams?.some((s) => s.codec_name === "aac");
				} catch {
					return false;
				}
			},
			{ timeout: 240000 },
		)
		.toBe(true);
	const audio = probe.streams.find((s) => s.codec_type === "audio"),
		video = probe.streams.find((s) => s.codec_type === "video");
	assert(video.codec_name === "h264");
	assert(Math.abs(Number(audio.duration) - Number(video.duration)) < 0.2);
	const volume = spawnSync(
		ffmpeg,
		[
			"-hide_banner",
			"-nostats",
			"-i",
			output,
			"-map",
			"0:a:0",
			"-af",
			"volumedetect",
			"-vn",
			"-f",
			"null",
			"-",
		],
		{ encoding: "utf8", windowsHide: true, timeout: 60000 },
	);
	assert.equal(volume.status, 0);
	const mean = Number(volume.stderr.match(/mean_volume:\s*(-?[\d.]+) dB/)?.[1]);
	assert(Number.isFinite(mean) && mean > -55);
	report.meanVolumeDb = mean;
	report.export = probe;
	assert((await hash(input)) === originalHash);
	report.checks.push("H264/AAC export and original media preservation");
	report.success = true;
} catch (error) {
	report.error = String(error);
	throw error;
} finally {
	if (app) await app.evaluate(({ app }) => app.exit(0)).catch(() => undefined);
	await fs.writeFile(path.join(work, "report.json"), JSON.stringify(report, null, 2));
	console.log(
		JSON.stringify({
			work,
			success: report.success,
			checks: report.checks,
			error: report.error,
		}),
	);
}
